dollar_bound_probe.source:
module probe_dollar;
  bit [7:0] u;
  bit signed [7:0] s;
  bit [7:0] lo8, hi8;
  bit [0:0] lo1;
  bit [1:0] u2;
  initial begin
    lo8 = 8'd3; hi8 = 8'd10; lo1 = 1'b1;
    u = 8'd5;
    $display("A u=5 [$:hi=10]=%b [lo=3:$]=%b [$:10]=%b [3:$]=%b", u inside {[$:hi8]},
             u inside {[lo8:$]}, u inside {[$:10]}, u inside {[3:$]});
    u = 8'd200;
    $display("B u=200 [$:hi=10]=%b [lo=3:$]=%b", u inside {[$:hi8]}, u inside {[lo8:$]});
    s = -8'sd5;
    $display("C s=-5 [$:hi=10]=%b [lo=3:$]=%b [$:10]=%b", s inside {[$:hi8]},
             s inside {[lo8:$]}, s inside {[$:10]});
    u2 = 2'b01;
    $display("D u2=01 [lo1=1:$]=%b [1:$]=%b", u2 inside {[lo1:$]}, u2 inside {[1'b1:$]});
    u2 = 2'b11;
    $display("E u2=11 [lo1=1:$]=%b", u2 inside {[lo1:$]});
  end
endmodule
